/**
 * Service for interacting with the Mempool.space API
 * Base URL: https://mempool.space/api
 */

const BASE_URL = 'https://mempool.space/api';

export interface MempoolTransaction {
  txid: string;
  version: number;
  locktime: number;
  vin: MempoolInput[];
  vout: MempoolOutput[];
  size: number;
  weight: number;
  fee: number;
  status: {
    confirmed: boolean;
    block_height: number;
    block_hash: string;
    block_time: number;
  };
}

export interface MempoolInput {
  txid: string;
  vout: number;
  prevout: {
    scriptpubkey: string;
    scriptpubkey_asm: string;
    scriptpubkey_type: string;
    scriptpubkey_address: string;
    value: number;
  } | null;
  scriptsig: string;
  scriptsig_asm: string;
  is_coinbase: boolean;
  sequence: number;
}

export interface MempoolOutput {
  scriptpubkey: string;
  scriptpubkey_asm: string;
  scriptpubkey_type: string;
  scriptpubkey_address: string;
  value: number;
}

export async function getAddressTransactions(address: string): Promise<MempoolTransaction[]> {
  try {
    const response = await fetch(`${BASE_URL}/address/${address}/txs`);
    if (!response.ok) {
      if (response.status === 400) {
        throw new Error('Invalid Bitcoin address');
      }
      throw new Error(`Mempool API error: ${response.statusText}`);
    }
    return await response.json();
  } catch (error) {
    console.error('Error fetching address transactions:', error);
    throw error;
  }
}

export async function getTransaction(txid: string): Promise<MempoolTransaction> {
  try {
    const response = await fetch(`${BASE_URL}/tx/${txid}`);
    if (!response.ok) {
      throw new Error(`Mempool API error: ${response.statusText}`);
    }
    return await response.json();
  } catch (error) {
    console.error('Error fetching transaction details:', error);
    throw error;
  }
}
