import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAddressTransactions } from '@/lib/services/mempool';

export async function POST(request: Request) {
  try {
    const { address } = await request.json();

    if (!address || typeof address !== 'string') {
      return NextResponse.json({ error: 'Valid Bitcoin address is required' }, { status: 400 });
    }

    // Create the investigation record
    const investigation = await prisma.investigation.create({
      data: {
        address,
        status: 'fetching',
      },
    });

    // In a real production system, this would be queued to a background worker
    // For this MVP, we will fetch the data immediately before responding
    // Note: Next.js API routes have timeouts (e.g., 10s on Vercel hobby tier)
    // We are proceeding with synchronous fetch for the sake of the Walking Skeleton

    try {
      const txs = await getAddressTransactions(address);

      // Save Address if it doesn't exist
      await prisma.address.upsert({
        where: { address },
        update: {},
        create: { address },
      });

      // Update Investigation with count
      await prisma.investigation.update({
        where: { id: investigation.id },
        data: {
          transactionsAnalyzed: txs.length,
          status: 'completed',
          completedAt: new Date(),
        },
      });

      // We would normally loop through txs to populate Transactions, Inputs, Outputs here
      // For the sake of the MVP, we just count them and return success. 

      return NextResponse.json({
        investigationId: investigation.id,
        status: 'completed',
        transactionsAnalyzed: txs.length
      });

    } catch (fetchError) {
      console.error(fetchError);
      await prisma.investigation.update({
        where: { id: investigation.id },
        data: { status: 'failed' },
      });
      return NextResponse.json({ error: 'Failed to fetch blockchain data' }, { status: 502 });
    }

  } catch (error) {
    console.error('Error creating investigation:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}
